SELECT 'batch_009_cf66a64d_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0f2858ab-23e','sm-upload-2fa950da-a07','sm-upload-40ec654c-f08','sm-upload-5c324864-c88','sm-upload-5cd6f1b2-596','sm-upload-5d8c3e73-3b9','sm-upload-8492670d-25f','sm-upload-afdf5f4f-429','sm-upload-b4b6cc03-4a0','sm-upload-d1382210-3d5') AND album_id='al-fe774f1b1c6a6738d25d732bcf66a64d') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0f2858ab-23e','sm-upload-2fa950da-a07','sm-upload-40ec654c-f08','sm-upload-5c324864-c88','sm-upload-5cd6f1b2-596','sm-upload-5d8c3e73-3b9','sm-upload-8492670d-25f','sm-upload-afdf5f4f-429','sm-upload-b4b6cc03-4a0','sm-upload-d1382210-3d5') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-fe774f1b1c6a6738d25d732bcf66a64d' AND name='SE＞EN(Sya)SEVEN') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-fe774f1b1c6a6738d25d732bcf66a64d') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-fe774f1b1c6a6738d25d732bcf66a64d') AS calculated_size;
